#pragma once

#include <tesla.hpp>

class AlphaSymbol {
  private:
    s32       m_width;
    s32       m_height;
    const u8 *m_data;

  public:
    constexpr AlphaSymbol(const size_t width, const size_t height, const u8 *data)
        : m_width(width), m_height(height), m_data(data) {}

    void draw(const s32 x, const s32 y, tsl::gfx::Renderer *renderer, tsl::Color color) const {
        const u8 *ptr = m_data;
        const s32 xo  = x - m_width  / 2;
        const s32 yo  = y - m_height / 2;
        const u8  lim = static_cast<u8>(0xF * tsl::gfx::Renderer::s_opacity);
        for (s32 r = 0; r < m_height; r++) {
            for (s32 c = 0; c < m_width; c++) {
                const u8 a = static_cast<u8>(*ptr++ >> 4);
                if (a > 0) {
                    color.a = a < lim ? a : lim;
                    renderer->setPixelBlendSrc(xo + c, yo + r, color);
                }
            }
        }
    }
};

